-- Roles (not generated by Prisma migrate diff — applied before schema)
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'access_rw') THEN
    CREATE ROLE access_rw NOLOGIN NOINHERIT;
  END IF;
END $$;

DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'app_runtime') THEN
    EXECUTE 'GRANT access_rw TO app_runtime';
  END IF;
END $$;

-- CreateSchema
CREATE SCHEMA IF NOT EXISTS "access";

GRANT USAGE ON SCHEMA "access" TO access_rw;

-- CreateTable: role
-- UNIQUE NULLS NOT DISTINCT: two system roles (organization_id IS NULL) with the same name are
-- treated as duplicates. Standard UNIQUE would allow multiple NULLs (PG treats NULL != NULL).
-- PostgreSQL 15+ syntax; confirmed on staging (PostgreSQL 17.11).
CREATE TABLE "access"."role" (
    "id"              UUID          NOT NULL DEFAULT gen_random_uuid(),
    "name"            VARCHAR(64)   NOT NULL,
    "organization_id" UUID,
    "is_system"       BOOLEAN       NOT NULL DEFAULT false,
    "description"     TEXT,
    "created_at"      TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "role_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "role_name_organization_id_key"
  ON "access"."role"("name", "organization_id") NULLS NOT DISTINCT;

-- CreateTable: permission
CREATE TABLE "access"."permission" (
    "id"             UUID          NOT NULL DEFAULT gen_random_uuid(),
    "application_id" VARCHAR(64)   NOT NULL,
    "name"           VARCHAR(128)  NOT NULL,
    "description"    TEXT,
    "created_at"     TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "permission_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "permission_application_id_name_key"
  ON "access"."permission"("application_id", "name");

-- CreateTable: role_permission
CREATE TABLE "access"."role_permission" (
    "id"            UUID        NOT NULL DEFAULT gen_random_uuid(),
    "role_id"       UUID        NOT NULL,
    "permission_id" UUID        NOT NULL,
    "created_at"    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "role_permission_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "role_permission_role_id_permission_id_key"
  ON "access"."role_permission"("role_id", "permission_id");

-- CreateTable: application_access (per-member: organization_id + user_id + application_id)
CREATE TABLE "access"."application_access" (
    "id"              UUID        NOT NULL DEFAULT gen_random_uuid(),
    "organization_id" UUID        NOT NULL,
    "user_id"         UUID        NOT NULL,
    "application_id"  VARCHAR(64) NOT NULL,
    "role_in_app"     VARCHAR(64),
    "created_at"      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "application_access_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "application_access_organization_id_user_id_application_id_key"
  ON "access"."application_access"("organization_id", "user_id", "application_id");

-- CreateTable: resource_access_policy
CREATE TABLE "access"."resource_access_policy" (
    "id"              UUID        NOT NULL DEFAULT gen_random_uuid(),
    "organization_id" UUID        NOT NULL,
    "role_id"         UUID        NOT NULL,
    "resource_type"   VARCHAR(64) NOT NULL,
    "resource_id"     UUID,
    "created_at"      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "resource_access_policy_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "resource_access_policy_organization_id_role_id_idx"
  ON "access"."resource_access_policy"("organization_id", "role_id");

-- Foreign keys (Prisma 7 convention: ON DELETE CASCADE ON UPDATE CASCADE)
ALTER TABLE "access"."role_permission"
  ADD CONSTRAINT "role_permission_role_id_fkey"
  FOREIGN KEY ("role_id") REFERENCES "access"."role"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "access"."role_permission"
  ADD CONSTRAINT "role_permission_permission_id_fkey"
  FOREIGN KEY ("permission_id") REFERENCES "access"."permission"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- Grants
-- access_rw has SELECT on permission tables (written only at deploy via sync-permissions.ts)
-- and full INSERT/UPDATE/DELETE on application_access (written at runtime by grantApplicationAccess)
GRANT SELECT ON "access"."role" TO access_rw;
GRANT SELECT ON "access"."permission" TO access_rw;
GRANT SELECT ON "access"."role_permission" TO access_rw;
GRANT SELECT, INSERT, UPDATE, DELETE ON "access"."application_access" TO access_rw;
GRANT SELECT, INSERT, UPDATE, DELETE ON "access"."resource_access_policy" TO access_rw;

ALTER DEFAULT PRIVILEGES IN SCHEMA "access" GRANT SELECT ON TABLES TO access_rw;

-- RLS
ALTER TABLE "access"."role" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "access"."permission" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "access"."role_permission" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "access"."application_access" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "access"."resource_access_policy" ENABLE ROW LEVEL SECURITY;

-- System roles (organization_id IS NULL) are visible to all orgs for permission lookups
CREATE POLICY access_rw_role ON "access"."role"
  TO access_rw
  USING (
    organization_id IS NULL
    OR organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid
  );

-- Permissions are global (application-scoped, not org-scoped)
CREATE POLICY access_rw_permission ON "access"."permission"
  TO access_rw
  USING (true);

-- Role permissions: visible if the role is visible (system or org-scoped)
CREATE POLICY access_rw_role_permission ON "access"."role_permission"
  TO access_rw
  USING (
    EXISTS (
      SELECT 1 FROM "access"."role" r
      WHERE r.id = role_id
        AND (
          r.organization_id IS NULL
          OR r.organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid
        )
    )
  );

CREATE POLICY access_rw_application_access ON "access"."application_access"
  TO access_rw
  USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid)
  WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);

CREATE POLICY access_rw_resource_access_policy ON "access"."resource_access_policy"
  TO access_rw
  USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid)
  WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);

